// af-01 可运行示例：手写 SSE 解析器 + 故意在多字节字符中间切断的分片
// 运行方式：tsx af-01.ts（无依赖，浏览器里也能跑）

type Frame = { event: string; data: string; id?: string }

/** 把字节流切成完整的 SSE 帧；跨块的残包留在闭包里 */
function createSSEParser(onFrame: (f: Frame) => void) {
  const decoder = new TextDecoder('utf-8')
  let buffer = ''

  const emit = (raw: string) => {
    if (!raw.trim()) return
    let event = 'message'
    let id: string | undefined
    const dataLines: string[] = []
    for (const line of raw.split('\n')) {
      if (!line || line.startsWith(':')) continue // 空行与注释（心跳）
      const colon = line.indexOf(':')
      const field = colon === -1 ? line : line.slice(0, colon)
      // 只去掉字段名后的一个空格，绝不 trim（会吃掉 markdown 缩进）
      const value = colon === -1 ? '' : line.slice(colon + 1).replace(/^ /, '')
      if (field === 'data') dataLines.push(value)
      else if (field === 'event') event = value
      else if (field === 'id') id = value
    }
    if (dataLines.length) onFrame({ event, data: dataLines.join('\n'), id })
  }

  return {
    push(chunk: Uint8Array) {
      buffer += decoder.decode(chunk, { stream: true })
      let idx = buffer.indexOf('\n\n')
      while (idx >= 0) {
        emit(buffer.slice(0, idx))
        buffer = buffer.slice(idx + 2)
        idx = buffer.indexOf('\n\n')
      }
    },
    finish() {
      buffer += decoder.decode() // 冲出残余字节
      emit(buffer)               // 处理没有结尾空行的最后一帧
      buffer = ''
    },
  }
}

// ---- 验证：把同一段流按 3 字节一切，模拟跨块切断 ----
const raw = [
  'event: token\ndata: 你好\n\n',
  'event: token\ndata: 世界\n\n',
  'event: done\ndata: {"reason":"stop"}\n\n',
].join('')

const bytes = new TextEncoder().encode(raw)
const frames: Frame[] = []
const parser = createSSEParser((f) => frames.push(f))
for (let i = 0; i < bytes.length; i += 3) {
  parser.push(bytes.slice(i, i + 3))
}
parser.finish()

console.log(frames.map((f) => f.data).join('|'))
// 你好|世界|{"reason":"stop"}
console.log('帧数', frames.length) // 3

