// af-02 可运行示例：token 合并器 + Markdown 稳定前缀切分
// 运行方式：tsx af-02.ts

type Listener = (delta: string, full: string) => void

/** 把高频 token 合并成低频提交；提交的是增量 */
function createTokenMerger(intervalMs = 50) {
  let pending = ''
  let full = ''
  let timer: ReturnType<typeof setTimeout> | null = null
  const listeners = new Set<Listener>()

  const flush = () => {
    timer = null
    if (!pending) return
    const delta = pending
    pending = ''
    full += delta
    for (const fn of listeners) fn(delta, full)
  }

  return {
    push(token: string) {
      pending += token
      if (timer === null) timer = setTimeout(flush, intervalMs)
    },
    /** 流结束：立刻把残留提交掉 */
    end() {
      if (timer !== null) clearTimeout(timer)
      flush()
    },
    subscribe(fn: Listener) {
      listeners.add(fn)
      return () => listeners.delete(fn)
    },
    get text() {
      return full
    },
  }
}

/**
 * 稳定前缀：最后一个空行为界；若前缀里代码围栏为奇数，回退到围栏之前。
 * 返回 { stable, tail }，stable 可以整体解析 markdown，tail 只当纯文本渲染。
 */
function stablePrefix(text: string): { stable: string; tail: string } {
  let cut = text.lastIndexOf('\n\n')
  if (cut < 0) return { stable: '', tail: text }
  cut += 2
  const head = text.slice(0, cut)
  const fences = (head.match(/^```/gm) || []).length
  if (fences % 2 === 1) {
    const lastFence = head.lastIndexOf('```')
    // 回退到围栏所在行的行首
    const lineStart = head.lastIndexOf('\n', lastFence - 1) + 1
    return { stable: text.slice(0, lineStart), tail: text.slice(lineStart) }
  }
  return { stable: head, tail: text.slice(cut) }
}

// ---- 演示一：稳定前缀（同步，先输出）----
const partial = '说明文字\n\n```ts\nconst a = 1\n'
console.log(stablePrefix(partial))
// { stable: '说明文字\n\n', tail: '```ts\nconst a = 1\n' }

// ---- 演示二：token 合并（异步，稍后输出）----
const merger = createTokenMerger(50)
let flushes = 0
merger.subscribe((_delta, full) => {
  flushes++
  if (flushes <= 3) console.log('flush#', flushes, '长度', full.length)
})

const tokens = Array.from({ length: 800 }, (_, i) => String.fromCharCode(0x4e00 + (i % 200)))
const t0 = Date.now()
tokens.forEach((tk, i) => setTimeout(() => merger.push(tk), i * 5))
setTimeout(() => {
  merger.end()
  console.log('总字符', merger.text.length, '期望 800', 'flush 次数', flushes, '耗时约', Date.now() - t0, 'ms')
}, tokens.length * 5 + 200)

// af-03 可运行示例：requestId 守卫 + seq 去重 + 取消/错误分流
// 运行方式：tsx af-03.ts（用假服务端模拟乱序、重复、延迟回调）

type Ev = { seq: number; delta: string }
type FakeServer = (signal: AbortSignal, emit: (e: Ev) => void) => Promise<void>

/** 假服务端：先发 1、2，然后故意重复发 2，再发 3，最后延迟结束 */
const fakeServer: FakeServer = async (signal, emit) => {
  const wait = (ms: number) => new Promise((r) => setTimeout(r, ms))
  emit({ seq: 1, delta: 'A' })
  await wait(10)
  emit({ seq: 2, delta: 'B' })
  await wait(10)
  emit({ seq: 2, delta: 'B' }) // 重复
  await wait(10)
  emit({ seq: 3, delta: 'C' })
  await wait(30)
  if (signal.aborted) throw Object.assign(new Error('aborted'), { name: 'AbortError' })
}

function createStreamSession(handlers: {
  onDelta: (text: string) => void
  onStop: () => void
  onError: (msg: string) => void
  onDone: () => void
}) {
  let current = 0
  let controller: AbortController | null = null
  let lastSeq = 0
  let text = ''

  return {
    get text() {
      return text
    },
    send() {
      controller?.abort()
      controller = new AbortController()
      const my = ++current
      lastSeq = 0
      text = ''
      const signal = controller.signal
      const isStale = () => my !== current || signal.aborted

      fakeServer(signal, (ev) => {
        // ① 身份守卫：旧请求的迟到回调必须丢弃
        if (isStale()) return
        // ② seq 去重：重复/过期事件丢弃（注意是 <=）
        if (ev.seq <= lastSeq) return
        lastSeq = ev.seq
        text += ev.delta
        handlers.onDelta(ev.delta)
      })
        .then(() => {
          if (isStale()) return
          handlers.onDone()
        })
        .catch((err: Error) => {
          if (isStale()) return
          if (err.name === 'AbortError') handlers.onStop()
          else handlers.onError(err.message)
        })
    },
    stop() {
      controller?.abort()
    },
  }
}

// ---- 演示：连点两次，验证内容不会串 ----
const s = createStreamSession({
  onDelta: (d) => console.log('delta', d),
  onStop: () => console.log('stopped'),
  onError: (m) => console.log('error', m),
  onDone: () => console.log('done, text =', s.text),
})
s.send()
setTimeout(() => s.send(), 5) // 第二个请求在第一个还没结束时开始
setTimeout(() => console.log('final text =', s.text, '（应为 ABC，不带重复 B）'), 200)

// af-04 可运行示例：Part 模型 + 只更新最后一个 text part + 结构共享
// 运行方式：tsx af-04.ts

type PartStatus = 'streaming' | 'ok' | 'failed'
type TextPart = { type: 'text'; id: string; text: string; status: PartStatus }
type ToolCallPart = { type: 'tool_call'; id: string; name: string; args: unknown; status: 'calling' | 'ok' | 'failed' }
type ToolResultPart = { type: 'tool_result'; id: string; callId: string; result: unknown }
type Part = TextPart | ToolCallPart | ToolResultPart

type MsgStatus = 'streaming' | 'done' | 'error' | 'stopped'
type Message = { id: string; role: 'user' | 'assistant'; parts: Part[]; status: MsgStatus }

const lastAssistant = (msgs: Message[]) => {
  for (let i = msgs.length - 1; i >= 0; i--) if (msgs[i].role === 'assistant') return i
  return -1
}

/** 追加文本：只动最后一条 assistant 的最后一个 text part，其它消息引用不变 */
function applyDelta(msgs: Message[], delta: string): Message[] {
  const index = lastAssistant(msgs)
  if (index < 0) return msgs
  const msg = msgs[index]
  const parts = [...msg.parts]
  const tail = parts[parts.length - 1]
  if (tail && tail.type === 'text') {
    parts[parts.length - 1] = { ...tail, text: tail.text + delta }
  } else {
    parts.push({ type: 'text', id: `t-${msg.parts.length}`, text: delta, status: 'streaming' })
  }
  const next = [...msgs]
  next[index] = { ...msg, parts }
  return next
}

/** 工具结果按 callId 挂到对应位置，并把调用状态改成 ok */
function upsertToolResult(msgs: Message[], callId: string, result: unknown): Message[] {
  return msgs.map((m) => {
    const hit = m.parts.some((p) => p.type === 'tool_call' && p.id === callId)
    if (!hit) return m // 未命中：保持引用，让 memo 生效
    const parts: Part[] = []
    for (const p of m.parts) {
      if (p.type === 'tool_call' && p.id === callId) parts.push({ ...p, status: 'ok' })
      else parts.push(p)
    }
    parts.push({ type: 'tool_result', id: `r-${callId}`, callId, result })
    return { ...m, parts }
  })
}

// ---- 验证结构共享与顺序 ----
const user: Message = { id: 'u1', role: 'user', parts: [{ type: 'text', id: 't0', text: '今天天气？', status: 'ok' }], status: 'done' }
const a1: Message = { id: 'a1', role: 'assistant', parts: [], status: 'streaming' }
let msgs = [user, a1]

msgs = applyDelta(msgs, '我查一下')
msgs = applyDelta(msgs, '。')
msgs = [...msgs.slice(0, 1), { ...msgs[1], parts: [...msgs[1].parts, { type: 'tool_call', id: 'c1', name: 'get_weather', args: { city: '深圳' }, status: 'calling' }] }]
msgs = upsertToolResult(msgs, 'c1', { temp: 26, text: '多云' })
msgs = applyDelta(msgs, '今天多云，26 度。')

console.log(msgs[1].parts.map((p) => p.type).join(' → '))
// text → tool_call → tool_result → text
console.log('用户消息引用未变:', msgs[0] === user) // true
console.log('文本内容:', (msgs[1].parts[0] as TextPart).text) // 我查一下。

// af-05 可运行示例：按会话分片的 store，切走再回来流继续
// 运行方式：tsx af-05.ts

type StreamStatus = 'idle' | 'streaming' | 'incomplete' | 'error'
type Session = { id: string; title: string; messages: string[]; status: StreamStatus; reqId: number }

type State = { sessions: Record<string, Session>; activeId: string }

const makeSession = (id: string): Session => ({ id, title: id, messages: [], status: 'idle', reqId: 0 })

let state: State = { sessions: { a: makeSession('a'), b: makeSession('b') }, activeId: 'a' }
const listeners = new Set<() => void>()
const emit = () => listeners.forEach((l) => l())

/** 只替换目标会话，其它会话引用不变（切会话不重渲染别的会话） */
function patch(id: string, fn: (s: Session) => Session) {
  state = { ...state, sessions: { ...state.sessions, [id]: fn(state.sessions[id]) } }
  emit()
}

function setActive(id: string) {
  state = { ...state, activeId: id }
  emit()
}

/** 假服务端：每 15ms 吐一个字 */
function fakeStream(onToken: (t: string) => void): Promise<void> {
  const chars = '这是会话内容还在继续生成'.split('')
  return new Promise((resolve) => {
    let i = 0
    const timer = setInterval(() => {
      if (i >= chars.length) {
        clearInterval(timer)
        resolve()
        return
      }
      onToken(chars[i++])
    }, 15)
  })
}

function send(sessionId: string, text: string) {
  const reqId = state.sessions[sessionId].reqId + 1
  patch(sessionId, (s) => ({ ...s, messages: [...s.messages, `用户：${text}`], status: 'streaming', reqId }))

  // ⚠️ 所有写入都用参数 sessionId，绝不读 state.activeId
  let acc = ''
  fakeStream((t) => {
    if (state.sessions[sessionId].reqId !== reqId) return // 身份守卫
    acc += t
    patch(sessionId, (s) => ({ ...s, messages: [...s.messages.slice(0, -1), `助手：${acc}`] }))
  }).then(() => {
    if (state.sessions[sessionId].reqId === reqId) patch(sessionId, (s) => ({ ...s, status: 'idle' }))
  })
}

// ---- 演示：a 在流时切到 b，再切回 a ----
send('a', '你好')
setTimeout(() => setActive('b'), 20)
setTimeout(() => setActive('a'), 60)
setTimeout(() => {
  console.log('active =', state.activeId)
  console.log('a 的消息：', state.sessions.a.messages)
  console.log('a 的状态：', state.sessions.a.status) // idle（流正常跑完）
  console.log('b 未被污染：', state.sessions.b.messages.length === 0) // true
}, 500)

// af-06 可运行示例：三种订阅粒度下的通知次数差异
// 运行方式：tsx af-06.ts

type Msg = { id: string; text: string }
type State = { messages: Msg[] }

function createStore(initial: State) {
  let state = initial
  const listeners = new Set<() => void>()
  return {
    get: () => state,
    set(next: State) {
      state = next
      // 复制一份再遍历：监听器内部可能订阅/退订
      for (const l of [...listeners]) l()
    },
    subscribe(l: () => void) {
      listeners.add(l)
      return () => listeners.delete(l)
    },
  }
}

const store = createStore({ messages: [] })

// ① 订阅整个数组：任何写入都通知
let arrayHits = 0
store.subscribe(() => arrayHits++)

// ② 订阅单条消息：只有那条变了才通知（这里用 id 过滤模拟选择器）
function subscribeById(id: string, fn: () => void) {
  let prev = ''
  return store.subscribe(() => {
    const msg = store.get().messages.find((m) => m.id === id)
    const text = msg?.text ?? ''
    if (text !== prev) {
      prev = text
      fn()
    }
  })
}
let a1Hits = 0
let oldHits = 0
subscribeById('a1', () => a1Hits++)
subscribeById('old', () => oldHits++) // 一条不变的历史消息

// 初始化：一条历史消息 + 一条正在流的消息
store.set({
  messages: [
    { id: 'old', text: '这是一条很早的历史消息' },
    { id: 'a1', text: '' },
  ],
})

// 模拟 100 次 token 写入（每次都换新的 messages 与新对象，模拟不可变更新）
for (let i = 0; i < 100; i++) {
  const msgs = store.get().messages
  const next = msgs.map((m) => (m.id === 'a1' ? { ...m, text: m.text + '字' } : m))
  store.set({ messages: next })
}

console.log('数组订阅通知次数', arrayHits)   // 101（含初始化那次）
console.log('流式消息通知次数', a1Hits)      // 100
console.log('历史消息通知次数', oldHits)     // 0  ← 这就是细粒度订阅的价值

// af-07 可运行示例：事件流 → 可渲染时间线（纯函数归约 + 折叠摘要）
// 运行方式：tsx af-07.ts

type Ev =
  | { type: 'text.delta'; seq: number; delta: string }
  | { type: 'tool.start'; seq: number; callId: string; name: string; summary: string }
  | { type: 'tool.end'; seq: number; callId: string; ok: boolean; result: unknown; ms: number }
  | { type: 'run.finish'; seq: number; reason: 'stop' | 'error' }

type Item =
  | { kind: 'text'; text: string }
  | { kind: 'tool'; callId: string; name: string; summary: string; status: 'running' | 'ok' | 'failed'; result?: unknown; ms?: number }

type Timeline = { items: Item[]; finished: boolean; reason?: string }

const initial: Timeline = { items: [], finished: false }

function reduce(state: Timeline, ev: Ev): Timeline {
  switch (ev.type) {
    case 'text.delta': {
      const items = [...state.items]
      const last = items[items.length - 1]
      if (last && last.kind === 'text') items[items.length - 1] = { ...last, text: last.text + ev.delta }
      else items.push({ kind: 'text', text: ev.delta })
      return { ...state, items }
    }
    case 'tool.start':
      // 先插入 running，过程立刻可见，而不是等结果回来才出现
      return {
        ...state,
        items: [...state.items, { kind: 'tool', callId: ev.callId, name: ev.name, summary: ev.summary, status: 'running' }],
      }
    case 'tool.end': {
      const items = state.items.map((it) =>
        it.kind === 'tool' && it.callId === ev.callId
          ? { ...it, status: ev.ok ? ('ok' as const) : ('failed' as const), result: ev.result, ms: ev.ms }
          : it,
      )
      return { ...state, items }
    }
    case 'run.finish':
      return { ...state, finished: true, reason: ev.reason }
    default:
      return state
  }
}

/** 一行摘要：给折叠态用（真实项目里由服务端给，这里演示口径） */
function summarize(t: Timeline): string {
  const tools = t.items.filter((i) => i.kind === 'tool')
  const ms = tools.reduce((s, i) => s + (i.kind === 'tool' ? i.ms ?? 0 : 0), 0)
  const failed = tools.filter((i) => i.kind === 'tool' && i.status === 'failed').length
  if (!tools.length) return `思考 ${t.items.filter((i) => i.kind === 'text').length} 段`
  return `${tools.length} 次工具调用${failed ? `（${failed} 失败）` : ''} · ${(ms / 1000).toFixed(1)}s`
}

// ---- 演示：一次带工具调用的完整过程 ----
const events: Ev[] = [
  { type: 'text.delta', seq: 1, delta: '我先查一下文档。' },
  { type: 'tool.start', seq: 2, callId: 'c1', name: 'search_docs', summary: '搜索文档：退款政策' },
  { type: 'tool.end', seq: 3, callId: 'c1', ok: true, result: { hits: 3 }, ms: 1200 },
  { type: 'text.delta', seq: 4, delta: '查到了：退款需要 7 个工作日。' },
  { type: 'run.finish', seq: 5, reason: 'stop' },
]

const final = events.reduce(reduce, initial)
console.log(final.items.map((i) => (i.kind === 'text' ? `text(${i.text.length})` : `${i.name}:${i.status}`)).join(' | '))
// text(8) | search_docs:ok | text(16)
console.log('摘要：', summarize(final))
console.log('是否结束：', final.finished, final.reason)

// af-08 可运行示例：JSON Schema → 控件映射 + 结果渲染器分派 + 未知类型降级
// 运行方式：tsx af-08.ts

type Field = {
  type?: 'string' | 'number' | 'boolean' | 'array'
  enum?: string[]
  title?: string
  minimum?: number
  maximum?: number
  items?: Field
}

type Control = { kind: 'text' | 'number' | 'switch' | 'select' | 'list'; options?: string[]; hint: string }

/** schema 字段 → 控件描述（真实项目里这里返回 React 元素，逻辑一致） */
function renderField(name: string, f: Field, required: boolean): Control {
  // enum 优先：{type:'string', enum:[...]} 若先看 type 会退化成文本框
  if (f.enum?.length) return { kind: 'select', options: f.enum, hint: `${name}（必选 ${f.enum.length} 项之一）` }
  switch (f.type) {
    case 'number':
      return { kind: 'number', hint: `${name}：${f.minimum ?? '-∞'} ~ ${f.maximum ?? '+∞'}` }
    case 'boolean':
      return { kind: 'switch', hint: `${name}（开关）` }
    case 'array':
      return { kind: 'list', hint: `${name}（列表，元素类型 ${f.items?.type ?? 'unknown'}）` }
    default:
      return { kind: 'text', hint: `${name}${required ? '（必填）' : ''}` }
  }
}

/** 形状校验：只做前端即时反馈，服务端必须再校验一次 */
function validate(schema: { properties: Record<string, Field>; required?: string[] }, value: Record<string, unknown>): string[] {
  const errs: string[] = []
  for (const key of schema.required ?? []) {
    const v = value[key]
    if (v === undefined || v === null || v === '') errs.push(`${key} 必填`)
  }
  for (const [key, f] of Object.entries(schema.properties)) {
    const v = value[key]
    if (v === undefined) continue
    if (f.type === 'number' && typeof v === 'number') {
      if (f.minimum !== undefined && v < f.minimum) errs.push(`${key} 不能小于 ${f.minimum}`)
      if (f.maximum !== undefined && v > f.maximum) errs.push(`${key} 不能大于 ${f.maximum}`)
    }
    if (f.enum && typeof v === 'string' && !f.enum.includes(v)) errs.push(`${key} 必须是 ${f.enum.join(' / ')}`)
  }
  return errs
}

/** 结果渲染器分派：主类型 + 通配，未知类型必须降级 */
const RENDERERS: Record<string, string> = {
  'text/markdown': 'Markdown 渲染',
  'application/json': '可折叠 JSON 树',
  'text/x-diff': 'Diff 视图',
  'text/csv': '表格',
  'image/png': '图片',
  'image/jpeg': '图片',
  'image/svg+xml': '图片',
}

function pickRenderer(mime: string): string {
  if (RENDERERS[mime]) return RENDERERS[mime]
  const major = mime.split('/')[0] + '/*'
