// af-09 可运行示例：步骤耗时与用量归因 + 审批挂起/超时
// 运行方式：tsx af-09.ts

type Step = { id: string; kind: 'think' | 'tool' | 'answer'; label: string; ms: number; tokens: number }

function createRunTracker() {
  const started = new Map<string, number>()
  const steps: Step[] = []

  return {
    begin(id: string, kind: Step['kind'], label: string) {
      started.set(id, Date.now())
      return { id, kind, label }
    },
    end(id: string, tokens = 0) {
      const t0 = started.get(id)
      if (t0 === undefined) {
        // 协议不一致要暴露，不要静默
        console.warn('end 未匹配到 begin:', id)
        return
      }
      started.delete(id)
      const meta = steps.find((s) => s.id === id)
      if (!meta) return
      meta.ms = Date.now() - t0
      meta.tokens = tokens
    },
    register(id: string, kind: Step['kind'], label: string) {
      const s: Step = { id, kind, label, ms: 0, tokens: 0 }
      steps.push(s)
      return s
    },
    report() {
      const total = steps.reduce((s, x) => s + x.ms, 0)
      return {
        steps: steps.map((s) => ({ ...s })),
        totalMs: total,
        tokens: steps.reduce((s, x) => s + x.tokens, 0),
        slowest: steps.slice().sort((a, b) => b.ms - a.ms)[0],
      }
    },
  }
}

/** 审批：返回 promise，支持批准与超时，且清理定时器 */
function awaitApproval(timeoutMs = 2000): Promise<'approve' | 'reject' | 'timeout'> {
  return new Promise((resolve) => {
    const timer = setTimeout(() => resolve('timeout'), timeoutMs)
    // 真实项目里把 resolve 存起来，供 approve(callId) / reject(callId) 调用
    const done = (v: 'approve' | 'reject') => {
      clearTimeout(timer)
      resolve(v)
    }
    ;(globalThis as unknown as { __approve: typeof done }).__approve = done
  })
}

// ---- 演示：三步任务 + 归因 ----
const tracker = createRunTracker()

async function run() {
  const s1 = tracker.register('s1', 'think', '规划步骤')
