// af-10 可运行示例：三层坐标换算 + 指针锚点缩放 + 命中测试
// 运行方式：tsx af-10.ts

type Pt = { x: number; y: number }
type Viewport = { x: number; y: number; k: number } // 平移 + 缩放
type Node = { id: string; x: number; y: number; w: number; h: number }

/** 屏幕坐标 → 图坐标（先减平移，再除缩放） */
const screenToWorld = (p: Pt, v: Viewport): Pt => ({ x: (p.x - v.x) / v.k, y: (p.y - v.y) / v.k })

/** 图坐标 → 屏幕坐标 */
const worldToScreen = (p: Pt, v: Viewport): Pt => ({ x: p.x * v.k + v.x, y: p.y * v.k + v.y })

/** 以指针为锚点缩放：指针下的世界坐标保持不动 */
function zoomAt(p: Pt, nextK: number, v: Viewport): Viewport {
  const world = screenToWorld(p, v)
  return { k: nextK, x: p.x - world.x * nextK, y: p.y - world.y * nextK }
}

/** 包围盒命中：从上层往下找（数组末尾优先） */
function hitTest(nodes: Node[], world: Pt): Node | null {
  for (let i = nodes.length - 1; i >= 0; i--) {
    const n = nodes[i]
    if (world.x >= n.x && world.x <= n.x + n.w && world.y >= n.y && world.y <= n.y + n.h) return n
  }
  return null
}

