// af-11 可运行示例：连线校验（类型 + 环检测）+ 命令栈（拖拽合并）
// 运行方式：tsx af-11.ts

type PortType = 'text' | 'image' | 'json' | 'any'
type Graph = { nodes: { id: string; inputs: Record<string, PortType>; outputs: Record<string, PortType> }[]; edges: Edge[] }
type Edge = { from: string; fromPort: string; to: string; toPort: string }

const nodeOf = (g: Graph, id: string) => g.nodes.find((n) => n.id === id)

/** 新边是否会让图成环：从 to 出发能否回到 from */
function createsCycle(g: Graph, e: Edge): boolean {
  const adj = new Map<string, string[]>()
  for (const x of g.edges) {
    if (!adj.has(x.from)) adj.set(x.from, [])
    adj.get(x.from)!.push(x.to)
  }
  const stack = [e.to]
  const seen = new Set<string>()
  while (stack.length) {
    const cur = stack.pop()!
    if (cur === e.from) return true
    if (seen.has(cur)) continue
    seen.add(cur)
    for (const nx of adj.get(cur) ?? []) stack.push(nx)
  }
  return false
}

/** 先便宜的类型校验，再贵的环检测 */
function canConnect(g: Graph, e: Edge): { ok: true } | { ok: false; reason: string } {
  const from = nodeOf(g, e.from)
  const to = nodeOf(g, e.to)
  if (!from || !to) return { ok: false, reason: '节点不存在' }
  if (e.from === e.to) return { ok: false, reason: '不能连到自身' }

  const outType = from.outputs[e.fromPort]
  const inType = to.inputs[e.toPort]
  if (!outType || !inType) return { ok: false, reason: '端口不存在' }
  if (outType !== 'any' && inType !== 'any' && outType !== inType) {
    return { ok: false, reason: `类型不匹配：${outType} → ${inType}` }
  }
  if (createsCycle(g, e)) return { ok: false, reason: '会形成环' }
  return { ok: true }
}

// ---- 命令栈：连续拖拽合并 ----
type Cmd = { key: string; label: string; apply: (g: Graph) => Graph; revert: (g: Graph) => Graph }

function createHistory(initial: Graph) {
  let graph = initial
  const undoStack: Cmd[] = []
  const redoStack: Cmd[] = []
  return {
    get graph() {
      return graph
    },
    exec(cmd: Cmd) {
      // 同一个 key 的连续操作合并成一条（拖拽）
      const top = undoStack[undoStack.length - 1]
      if (top && top.key === cmd.key) {
        undoStack[undoStack.length - 1] = { ...cmd, revert: top.revert } // 保留最初的 revert
      } else {
        undoStack.push(cmd)
      }
      redoStack.length = 0
      graph = cmd.apply(graph)
    },
    undo() {
      const cmd = undoStack.pop()
      if (!cmd) return
      graph = cmd.revert(graph)
      redoStack.push(cmd)
    },
    get depth() {
      return undoStack.length
    },
  }
}

