// af-12 可运行示例：窗口化列表（高度缓存 + 二分定位 + 锚点保持）
// 运行方式：tsx af-12.ts

type Range = { start: number; end: number }

function createLayout(count: number, estimate: number) {
  const heights = new Map<number, number>()
  const heightOf = (i: number) => heights.get(i) ?? estimate

  /** 前缀和偏移（示例用简单累计，几十万项时要换 Fenwick 树做增量） */
  function offsets(): number[] {
    const out = new Array<number>(count + 1)
    out[0] = 0
    for (let i = 0; i < count; i++) out[i + 1] = out[i] + heightOf(i)
    return out
  }

  /** 二分找起点，再顺序累计到超出视口 */
  function visibleRange(scrollTop: number, viewportH: number): Range {
    const off = offsets()
    let lo = 0
    let hi = count - 1
    while (lo < hi) {
      const mid = (lo + hi + 1) >> 1
      if (off[mid] <= scrollTop) lo = mid
      else hi = mid - 1
    }
    let end = lo
    while (end < count && off[end + 1] - scrollTop <= viewportH) end++
    return { start: lo, end: Math.min(count, end) }
  }

  return {
    heightOf,
    offsets,
    visibleRange,
    measure(i: number, h: number) {
      heights.set(i, h)
    },
    totalHeight() {
      return offsets()[count]
    },
  }
}

